import{_ as n,o,c as e,a0 as i}from"./chunks/framework.BhkMvQqH.js";const h=JSON.parse('{"title":"Auth & Onboarding — Use Cases","description":"","frontmatter":{},"headers":[],"relativePath":"tests/use-cases/auth-onboarding.md","filePath":"tests/use-cases/auth-onboarding.md"}'),r={name:"tests/use-cases/auth-onboarding.md"};function t(s,a,l,u,c,g){return o(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="auth-onboarding-—-use-cases" tabindex="-1">Auth &amp; Onboarding — Use Cases <a class="header-anchor" href="#auth-onboarding-—-use-cases" aria-label="Permalink to &quot;Auth &amp; Onboarding — Use Cases&quot;">​</a></h1><h2 id="uc-auth-001-login-exitoso-con-email-y-contrasena" tabindex="-1">UC-AUTH-001: Login exitoso con email y contraseña <a class="header-anchor" href="#uc-auth-001-login-exitoso-con-email-y-contrasena" aria-label="Permalink to &quot;UC-AUTH-001: Login exitoso con email y contraseña&quot;">​</a></h2><ul><li><strong>Screen</strong>: Login</li><li><strong>Dado</strong> un usuario registrado con email válido y contraseña correcta</li><li><strong>Cuando</strong> el usuario ingresa sus credenciales y presiona &quot;Iniciar sesión&quot;</li><li><strong>Entonces</strong> el sistema valida las credenciales contra Supabase Auth</li><li><strong>Y</strong> redirige al dashboard correspondiente al rol del usuario</li><li><strong>Y</strong> almacena el JWT en localStorage</li></ul><h2 id="uc-auth-002-login-con-email-inexistente" tabindex="-1">UC-AUTH-002: Login con email inexistente <a class="header-anchor" href="#uc-auth-002-login-con-email-inexistente" aria-label="Permalink to &quot;UC-AUTH-002: Login con email inexistente&quot;">​</a></h2><ul><li><strong>Screen</strong>: Login</li><li><strong>Dado</strong> un email que no está registrado en el sistema</li><li><strong>Cuando</strong> el usuario intenta iniciar sesión con ese email</li><li><strong>Entonces</strong> el sistema muestra &quot;Credenciales inválidas&quot;</li><li><strong>Y</strong> no se crea ninguna sesión</li></ul><h2 id="uc-auth-003-login-con-contrasena-incorrecta" tabindex="-1">UC-AUTH-003: Login con contraseña incorrecta <a class="header-anchor" href="#uc-auth-003-login-con-contrasena-incorrecta" aria-label="Permalink to &quot;UC-AUTH-003: Login con contraseña incorrecta&quot;">​</a></h2><ul><li><strong>Screen</strong>: Login</li><li><strong>Dado</strong> un usuario registrado con email válido</li><li><strong>Cuando</strong> el usuario ingresa una contraseña incorrecta</li><li><strong>Entonces</strong> el sistema muestra &quot;Credenciales inválidas&quot;</li><li><strong>Y</strong> registra el intento fallido</li></ul><h2 id="uc-auth-004-registro-exitoso-de-nuevo-usuario" tabindex="-1">UC-AUTH-004: Registro exitoso de nuevo usuario <a class="header-anchor" href="#uc-auth-004-registro-exitoso-de-nuevo-usuario" aria-label="Permalink to &quot;UC-AUTH-004: Registro exitoso de nuevo usuario&quot;">​</a></h2><ul><li><strong>Screen</strong>: Sign Up</li><li><strong>Dado</strong> un usuario no registrado con email y datos válidos</li><li><strong>Cuando</strong> el usuario completa el formulario de registro</li><li><strong>Entonces</strong> el sistema crea la cuenta en Supabase Auth</li><li><strong>Y</strong> redirige al Organization Onboarding Wizard</li></ul><h2 id="uc-auth-005-registro-con-email-duplicado" tabindex="-1">UC-AUTH-005: Registro con email duplicado <a class="header-anchor" href="#uc-auth-005-registro-con-email-duplicado" aria-label="Permalink to &quot;UC-AUTH-005: Registro con email duplicado&quot;">​</a></h2><ul><li><strong>Screen</strong>: Sign Up</li><li><strong>Dado</strong> un email que ya está registrado en el sistema</li><li><strong>Cuando</strong> el usuario intenta registrarse con ese email</li><li><strong>Entonces</strong> el sistema muestra &quot;El email ya está registrado&quot;</li><li><strong>Y</strong> no crea la cuenta</li></ul><h2 id="uc-auth-006-completar-wizard-de-onboarding" tabindex="-1">UC-AUTH-006: Completar wizard de onboarding <a class="header-anchor" href="#uc-auth-006-completar-wizard-de-onboarding" aria-label="Permalink to &quot;UC-AUTH-006: Completar wizard de onboarding&quot;">​</a></h2><ul><li><strong>Screen</strong>: Organization Onboarding Wizard</li><li><strong>Dado</strong> un usuario que acaba de registrarse</li><li><strong>Cuando</strong> el usuario completa todos los pasos del wizard</li><li><strong>Entonces</strong> el sistema crea la organización con los datos provistos</li><li><strong>Y</strong> redirige al dashboard de la organización</li></ul><h2 id="uc-auth-007-cancelar-wizard-de-onboarding" tabindex="-1">UC-AUTH-007: Cancelar wizard de onboarding <a class="header-anchor" href="#uc-auth-007-cancelar-wizard-de-onboarding" aria-label="Permalink to &quot;UC-AUTH-007: Cancelar wizard de onboarding&quot;">​</a></h2><ul><li><strong>Screen</strong>: Organization Onboarding Wizard</li><li><strong>Dado</strong> un usuario en medio del wizard de onboarding</li><li><strong>Cuando</strong> el usuario cancela el proceso</li><li><strong>Entonces</strong> el sistema no crea ninguna organización</li><li><strong>Y</strong> redirige a la pantalla de Sign Up</li></ul><h2 id="uc-auth-008-cambiar-de-tenant-exitosamente" tabindex="-1">UC-AUTH-008: Cambiar de tenant exitosamente <a class="header-anchor" href="#uc-auth-008-cambiar-de-tenant-exitosamente" aria-label="Permalink to &quot;UC-AUTH-008: Cambiar de tenant exitosamente&quot;">​</a></h2><ul><li><strong>Screen</strong>: Tenant Switcher</li><li><strong>Dado</strong> un usuario con acceso a múltiples organizaciones</li><li><strong>Cuando</strong> el usuario selecciona otra organización del selector</li><li><strong>Entonces</strong> el sistema cambia el contexto de tenant</li><li><strong>Y</strong> recarga el dashboard con los datos de la nueva organización</li></ul><h2 id="uc-auth-009-tenant-switcher-sin-organizaciones-disponibles" tabindex="-1">UC-AUTH-009: Tenant Switcher sin organizaciones disponibles <a class="header-anchor" href="#uc-auth-009-tenant-switcher-sin-organizaciones-disponibles" aria-label="Permalink to &quot;UC-AUTH-009: Tenant Switcher sin organizaciones disponibles&quot;">​</a></h2><ul><li><strong>Screen</strong>: Tenant Switcher</li><li><strong>Dado</strong> un usuario que pertenece a una sola organización</li><li><strong>Cuando</strong> el usuario abre el Tenant Switcher</li><li><strong>Entonces</strong> el sistema oculta el selector o lo muestra deshabilitado</li></ul>',19)])])}const m=n(r,[["render",t]]);export{h as __pageData,m as default};
